 84	/// A fully validated distributed-control projection for one flattened top.
 85	///
 86	/// Construction is read-only and happens before codegen clears the attached
 87	/// HLS body. Once this value exists, every controller placement and every
 88	/// required typed route is known to be complete and directionally consistent.
 89	#[derive(Debug)]
 90	pub struct DistributedControlPlan {
 91	    children: BTreeMap<String, ChildControlPlan>,
 92	    flush_cycles: u32,
 93	}
 94	
 95	impl DistributedControlPlan {
 96	    #[allow(
 97	        clippy::too_many_lines,
 98	        reason = "the exact route-set validation is clearest as one transaction"
 99	    )]
100	    pub(super) fn from_floorplan(
101	        state: &TopologyWithRtl,
102	        task_name: &str,
103	        mmap_connections: &BTreeMap<String, MMapConnection>,
104	    ) -> Result<Option<Self>, CodegenError> {
105	        let Some(floorplan) = state.floorplan.as_ref() else {
106	            return Ok(None);
107	        };
108	        let has_marker = floorplan
109	            .regions
110	            .contains_key(global_controller_instance_name());
111	        let has_routes = floorplan
112	            .routes
113	            .iter()
114	            .any(|route| matches!(route.channel, RoutedChannel::Control { .. }));
115	        if !has_marker {
116	            if has_routes {
117	                return Err(invalid_floorplan(
118	                    "control routes are present without a global controller placement",
119	                ));
120	            }
121	            return Ok(None);
122	        }
123	        if task_name != state.design.top || !state.supports_distributed_control() {
124	            return Err(invalid_floorplan(format!(
125	                "global controller placement cannot be realized for task '{task_name}'",
126	            )));
127	        }
128	
129	        let task = state
130	            .design
131	            .tasks
132	            .get(task_name)
133	            .ok_or_else(|| CodegenError::TaskNotFound(task_name.to_owned()))?;
134	        let global_region = floorplan
135	            .regions
136	            .get(global_controller_instance_name())
137	            .expect("marker was checked");
138	        match (
139	            state.top_instantiates_control_s_axi(),
140	            floorplan.regions.get("control_s_axi_U"),
141	        ) {
142	            (true, None) => {
143	                return Err(invalid_floorplan(
144	                    "top control AXI-Lite is missing placement 'control_s_axi_U'",
145	                ));
146	            }
147	            (true, Some(control_region)) if control_region != global_region => {
148	                return Err(invalid_floorplan(format!(
149	                    "control_s_axi_U is placed in '{control_region}', expected global controller region '{global_region}'",
150	                )));
151	            }
152	            (false, Some(_)) => {
153	                return Err(invalid_floorplan(
154	                    "unexpected control_s_axi_U placement without a generated top control AXI-Lite block",
155	                ));
156	            }
157	            (true, Some(_)) | (false, None) => {}
158	        }
159	        let global_slot = parse_atomic_region(global_region).ok_or_else(|| {
160	            invalid_floorplan(format!(
161	                "global controller has non-atomic placement '{global_region}'",
162	            ))
163	        })?;
164	
165	        let mut child_entries = Vec::<ChildEntry>::new();
166	        let mut known_instances = BTreeSet::new();
167	        for (child_name, instances) in &task.tasks {
168	            for (index, instance) in instances.iter().enumerate() {
169	                let logical_name = instance.canonical_name(child_name, index).into_owned();
170	                if !known_instances.insert(logical_name.clone()) {
171	                    return Err(invalid_floorplan(format!(
172	                        "flattened child instance '{logical_name}' is not unique",
173	                    )));
174	                }
175	                child_entries.push(ChildEntry {
176	                    instance: logical_name,
177	                    definition: child_name.clone(),
178	                    is_autorun: instance.step < 0,
179	                    args: instance.args.clone(),
180	                });
181	            }
182	        }
183	
184	        let mut planned_routes = BTreeMap::<(String, ControlChannel), FeedForwardRoute>::new();
185	        let mut max_data_latency = 0_u32;
186	        for route in &floorplan.routes {
187	            let body_level = u32::try_from(route.reg_regions.len())
188	                .map_err(|_| invalid_floorplan("pipeline Body level exceeds u32"))?;
189	            let latency = body_level
190	                .checked_add(2)
191	                .ok_or_else(|| invalid_floorplan("pipeline latency exceeds u32"))?;
192	            let RoutedChannel::Control { instance, channel } = &route.channel else {
193	                max_data_latency = max_data_latency.max(latency);
194	                continue;
195	            };
196	            if !known_instances.contains(instance) {
197	                return Err(invalid_floorplan(format!(
198	                    "control route names unknown child instance '{instance}'",
199	                )));
200	            }
201	            let planned = FeedForwardRoute {
202	                path: route.route.clone(),
203	                scheme: route.scheme,
204	                reg_regions: route.reg_regions.clone(),
205	                body_level,
206	                latency,
207	            };
208	            if planned_routes
209	                .insert((instance.clone(), *channel), planned)
210	                .is_some()
211	            {
212	                return Err(invalid_floorplan(format!(
213	                    "child '{instance}' has more than one {channel:?} route",
214	                )));
215	            }
216	        }
217	
218	        let mut children = BTreeMap::new();
219	        let mut flush_cycles = 0;
220	        let mut max_reset_latency = 0;
221	        for ChildEntry {
222	            instance,
223	            definition,
224	            is_autorun,
225	            args,
226	        } in child_entries
227	        {
228	            let child_region = floorplan.regions.get(&instance).ok_or_else(|| {
229	                invalid_floorplan(format!("child '{instance}' has no instance placement"))
230	            })?;
231	            let child_slot = parse_atomic_region(child_region).ok_or_else(|| {
232	                invalid_floorplan(format!(
233	                    "child '{instance}' has non-atomic placement '{child_region}'",
234	                ))
235	            })?;
236	            let local_name = local_controller_instance_name(&instance);
237	            let local_region = floorplan.regions.get(&local_name).ok_or_else(|| {
238	                invalid_floorplan(format!(
239	                    "child '{instance}' has no local controller placement '{local_name}'",
240	                ))
241	            })?;
242	            if local_region != child_region {
243	                return Err(invalid_floorplan(format!(
