  1	//! Async mmap bridge wiring.
  2	//!
  3	//! Lower HLS tasks expose `tapa::async_mmap` as FIFO-style channels
  4	//! (`mem_read_addr_s_din`, `mem_read_data_s_dout`, etc.).  Parent tasks
  5	//! connect those channels to the shared AXI fabric through `async_mmap`.
  6	
  7	use std::collections::BTreeSet;
  8	
  9	use tapa_protocol::{
 10	    HANDSHAKE_CLK, ISTREAM_SUFFIXES, M_AXI_PORTS, M_AXI_PREFIX, M_AXI_SUFFIXES_COMPACT,
 11	    OSTREAM_SUFFIXES,
 12	};
 13	use tapa_rtl::builder::{Expr, ModuleInstance, ParamArg, PortArg};
 14	use tapa_rtl::module::sanitize_array_name;
 15	use tapa_rtl::mutation::{wide_wire, wire, MutableModule};
 16	use tapa_rtl::VerilogModule;
 17	
 18	pub const READ_ADDR: &str = "read_addr";
 19	pub const READ_DATA: &str = "read_data";
 20	pub const WRITE_ADDR: &str = "write_addr";
 21	pub const WRITE_DATA: &str = "write_data";
 22	pub const WRITE_RESP: &str = "write_resp";
 23	pub const AXI_ADDR_WIDTH: u32 = 64;
 24	pub const AXI_ID_WIDTH: u32 = 1;
 25	
 26	const TAGS: &[&str] = &[READ_ADDR, READ_DATA, WRITE_ADDR, WRITE_DATA, WRITE_RESP];
 27	
 28	/// AXI directions that survive synthesis in one FIFO-style async mmap leaf.
 29	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 30	pub struct EnabledAxiDirections {
 31	    pub read: bool,
 32	    pub write: bool,
 33	}
 34	
 35	fn tag_suffixes(tag: &str) -> &'static [&'static str] {
 36	    match tag {
 37	        READ_ADDR | WRITE_ADDR | WRITE_DATA => OSTREAM_SUFFIXES,
 38	        READ_DATA | WRITE_RESP => ISTREAM_SUFFIXES,
 39	        _ => &[],
 40	    }
 41	}
 42	
 43	fn tag_data_width(tag: &str, suffix: &str, data_width: u32) -> u32 {
 44	    if !matches!(suffix, "_din" | "_dout") {
 45	        return 1;
 46	    }
 47	    match tag {
 48	        READ_ADDR | WRITE_ADDR => 64,
 49	        WRITE_RESP => 8,
 50	        _ => data_width,
 51	    }
 52	}
 53	
 54	pub fn signal_name(base: &str, tag: &str, suffix: &str) -> String {
 55	    let suffix = suffix.trim_start_matches('_');
 56	    format!("{}_{}__{suffix}", sanitize_array_name(base), tag)
 57	}
 58	
 59	pub fn bridge_base_from_m_axi_prefix(prefix: &str) -> String {
 60	    prefix
 61	        .strip_prefix(M_AXI_PREFIX)
 62	        .unwrap_or(prefix)
 63	        .to_owned()
 64	}
 65	
 66	pub fn active_tags(child_rtl: &VerilogModule, child_port: &str) -> BTreeSet<&'static str> {
 67	    TAGS.iter()
 68	        .copied()
 69	        .filter(|tag| {
 70	            let prefix = format!("{child_port}_{tag}");
 71	            tag_suffixes(tag).iter().any(|suffix| {
 72	                child_rtl.find_port_by_affixes(&prefix, suffix).is_some()
 73	                    || child_rtl
 74	                        .find_port_by_affixes(&format!("{prefix}_peek"), suffix)
 75	                        .is_some()
 76	            }) || child_rtl.find_port_by_affixes(&prefix, "_offset").is_some()
 77	        })
 78	        .collect()
 79	}
 80	
 81	/// Conservatively determine which AXI halves a FIFO-style async mmap uses.
 82	///
 83	/// Vitis HLS can retain every async FIFO port even when one direction is
 84	/// unused. A direction is disabled only when every present activity output in
 85	/// that group is an unconditional continuous assignment to zero. Missing or
 86	/// otherwise ambiguous activity outputs keep a present group enabled.
 87	pub fn enabled_axi_directions(
 88	    child_rtl: &VerilogModule,
 89	    child_port: &str,
 90	    tags: &BTreeSet<&'static str>,
 91	) -> EnabledAxiDirections {
 92	    let source = strip_verilog_comments(&child_rtl.source);
 93	    let group_enabled = |group: &[(&str, &str)]| {
 94	        for &(tag, activity_suffix) in group {
 95	            if !tags.contains(tag) {
 96	                continue;
 97	            }
 98	            let prefix = format!("{child_port}_{tag}");
 99	            let Some(port) = child_rtl.find_port_by_affixes(&prefix, activity_suffix) else {
100	                return true;
101	            };
102	            if !has_unconditional_zero_assign(&source, &port.name) {
103	                return true;
104	            }
105	        }
106	        false
107	    };
108	
109	    EnabledAxiDirections {
110	        read: group_enabled(&[(READ_ADDR, "_write"), (READ_DATA, "_read")]),
111	        write: group_enabled(&[
112	            (WRITE_ADDR, "_write"),
113	            (WRITE_DATA, "_write"),
114	            (WRITE_RESP, "_read"),
115	        ]),
116	    }
117	}
118	
119	/// Whether codegen will bind this async mmap as a direct compact M-AXI child
120	/// instead of inserting the FIFO-to-AXI bridge.
121	pub fn has_direct_m_axi_ports(child_rtl: &VerilogModule, child_port: &str) -> bool {
122	    child_rtl
123	        .find_port(&format!("{child_port}_offset"))
124	        .is_some()
125	        || M_AXI_SUFFIXES_COMPACT.iter().any(|suffix| {
126	            child_rtl
127	                .find_port(&format!("{M_AXI_PREFIX}{child_port}{suffix}"))
128	                .is_some()
129	        })
130	}
131	
132	fn strip_verilog_comments(source: &str) -> String {
133	    let mut result = String::with_capacity(source.len());
134	    let mut chars = source.chars().peekable();
135	    while let Some(ch) = chars.next() {
136	        if ch != '/' {
137	            result.push(ch);
138	            continue;
139	        }
140	        match chars.peek().copied() {
141	            Some('/') => {
142	                let _ = chars.next();
143	                for comment in chars.by_ref() {
144	                    if comment == '\n' {
145	                        result.push('\n');
146	                        break;
147	                    }
148	                }
149	            }
150	            Some('*') => {
151	                let _ = chars.next();
152	                let mut previous = '\0';
153	                for comment in chars.by_ref() {
154	                    if previous == '*' && comment == '/' {
155	                        break;
156	                    }
157	                    previous = comment;
158	                }
159	                result.push(' ');
160	            }
161	            _ => result.push(ch),
162	        }
163	    }
164	    result
165	}
166	
167	fn has_unconditional_zero_assign(source: &str, port: &str) -> bool {
168	    source.split(';').any(|statement| {
169	        let statement = statement.trim();
170	        let Some(assign) = statement.strip_prefix("assign") else {
171	            return false;
172	        };
173	        let Some((lhs, rhs)) = assign.split_once('=') else {
174	            return false;
175	        };
176	        lhs.trim() == port && is_zero_literal(rhs.trim())
177	    })
178	}
179	
180	fn is_zero_literal(literal: &str) -> bool {
181	    let mut literal = literal.trim();
182	    while let Some(inner) = literal
183	        .strip_prefix('(')
184	        .and_then(|value| value.strip_suffix(')'))
185	    {
186	        literal = inner.trim();
187	    }
188	    let compact = literal.replace('_', "");
189	    if compact == "0" || compact == "'0" {
190	        return true;
191	    }
192	    let Some((width, value)) = compact.split_once('\'') else {
193	        return false;
194	    };
195	    if width.is_empty() || !width.chars().all(|ch| ch.is_ascii_digit()) {
196	        return false;
197	    }
198	    let value = value
199	        .strip_prefix('s')
200	        .or_else(|| value.strip_prefix('S'))
201	        .unwrap_or(value);
202	    let Some(digits) = value
203	        .get(1..)
204	        .filter(|_| value.starts_with(['b', 'B', 'o', 'O', 'd', 'D', 'h', 'H']))
205	    else {
206	        return false;
207	    };
208	    !digits.is_empty() && digits.chars().all(|ch| ch == '0')
209	}
210	
211	pub fn child_connection_expr(base: &str, tag: &str, suffix: &str) -> Expr {
212	    let signal = Expr::ident(signal_name(base, tag, suffix));
213	    if matches!((tag, suffix), (READ_DATA | WRITE_RESP, "_dout")) {
214	        Expr::concat(vec![Expr::lit("1'b0"), signal])
215	    } else {
216	        signal
217	    }
218	}
219	
220	pub fn child_portargs(
221	    child_rtl: &VerilogModule,
222	    child_port: &str,
223	    bridge_base: &str,
224	    offset_signal: &str,
225	) -> Vec<PortArg> {
226	    let mut ports = Vec::new();
227	    for &tag in TAGS {
228	        let prefix = format!("{child_port}_{tag}");
229	        for &suffix in tag_suffixes(tag) {
230	            if let Some(port) = child_rtl.find_port_by_affixes(&prefix, suffix) {
231	                ports.push(PortArg::new(
232	                    port.name.clone(),
233	                    child_connection_expr(bridge_base, tag, suffix),
234	                ));
235	            }
236	            if matches!(tag, READ_DATA | WRITE_RESP) {
237	                let peek_prefix = format!("{prefix}_peek");
238	                if matches!(suffix, "_dout" | "_empty_n") {
239	                    if let Some(port) = child_rtl.find_port_by_affixes(&peek_prefix, suffix) {
240	                        ports.push(PortArg::new(
241	                            port.name.clone(),
242	                            child_connection_expr(bridge_base, tag, suffix),
243	                        ));
244	                    }
245	                }
246	            }
247	        }
248	        if tag.ends_with("_addr") {
249	            if let Some(port) = child_rtl.find_port_by_affixes(&prefix, "_offset") {
250	                ports.push(PortArg::new(port.name.clone(), Expr::ident(offset_signal)));
251	            }
252	        }
253	    }
254	    ports
255	}
256	
257	pub fn add_bridge_signals(
258	    module: &mut MutableModule,
259	    bridge_base: &str,
260	    active_tags: &BTreeSet<&'static str>,
261	    data_width: u32,
262	) {
263	    for &tag in active_tags {
264	        for &suffix in tag_suffixes(tag) {
265	            let name = signal_name(bridge_base, tag, suffix);
266	            let width = tag_data_width(tag, suffix, data_width);
267	            let signal = if width > 1 {
268	                wide_wire(&name, &(width - 1).to_string(), "0")
269	            } else {
270	                wire(&name)
271	            };
272	            let _ = module.add_signal(signal);
273	        }
274	    }
275	}
276	
277	#[allow(
278	    clippy::too_many_arguments,
279	    reason = "bridge wiring keeps the active and inactive AXI paths explicit"
280	)]
281	pub fn build_bridge_instance(
282	    bridge_base: &str,
283	    instance_name: &str,
284	    active_m_axi_prefix: &str,
285	    inactive_m_axi_prefix: &str,
286	    active_tags: &BTreeSet<&'static str>,
287	    enabled: EnabledAxiDirections,
288	    data_width: u32,
289	    connect_optional_axi_ports: bool,
290	    reset: Expr,
291	) -> ModuleInstance {
292	    let bytes = data_width / 8;
293	    let bytes_log = if bytes <= 1 {
294	        0
295	    } else {
296	        (bytes - 1).ilog2() + 1
297	    };
