304	        ParamArg::new("DataWidthBytesLog", Expr::int(u64::from(bytes_log))),
305	        ParamArg::new("AddrWidth", Expr::int(u64::from(AXI_ADDR_WIDTH))),
306	        ParamArg::new("WaitTimeWidth", Expr::int(2)),
307	        ParamArg::new("MaxWaitTime", Expr::int(3)),
308	        ParamArg::new("BurstLenWidth", Expr::int(9)),
309	        ParamArg::new("MaxBurstLen", Expr::int(u64::from(max_burst_len))),
310	        ParamArg::new(
311	            "EnableReadChannel",
312	            Expr::int(u64::from(u8::from(enabled.read))),
313	        ),
314	        ParamArg::new(
315	            "EnableWriteChannel",
316	            Expr::int(u64::from(u8::from(enabled.write))),
317	        ),
318	    ];
319	
320	    let mut ports = vec![
321	        PortArg::new("clk", Expr::ident(HANDSHAKE_CLK)),
322	        PortArg::new("rst", reset),
323	    ];
324	
325	    for channel in ["AW", "W", "B", "AR", "R"] {
326	        let channel_enabled = match channel {
327	            "AR" | "R" => enabled.read,
328	            "AW" | "W" | "B" => enabled.write,
329	            _ => unreachable!("known AXI channel"),
330	        };
331	        let channel_prefix = if channel_enabled {
