336	        if let Some(subports) = M_AXI_PORTS.get(channel) {
337	            for &(subport, _) in *subports {
338	                let suffix = format!("_{channel}{subport}");
339	                let is_compact = M_AXI_SUFFIXES_COMPACT.contains(&suffix.as_str());
