 81	/// Conservatively determine which AXI halves a FIFO-style async mmap uses.
 82	///
 83	/// Vitis HLS can retain every async FIFO port even when one direction is
 84	/// unused. A direction is disabled only when every present activity output in
 85	/// that group is an unconditional continuous assignment to zero. Missing or
 86	/// otherwise ambiguous activity outputs keep a present group enabled.
 87	pub fn enabled_axi_directions(
 88	    child_rtl: &VerilogModule,
 89	    child_port: &str,
 90	    tags: &BTreeSet<&'static str>,
 91	) -> EnabledAxiDirections {
 92	    let source = strip_verilog_comments(&child_rtl.source);
 93	    let group_enabled = |group: &[(&str, &str)]| {
 94	        for &(tag, activity_suffix) in group {
 95	            if !tags.contains(tag) {
 96	                continue;
 97	            }
 98	            let prefix = format!("{child_port}_{tag}");
 99	            let Some(port) = child_rtl.find_port_by_affixes(&prefix, activity_suffix) else {
100	                return true;
101	            };
102	            if !has_unconditional_zero_assign(&source, &port.name) {
103	                return true;
104	            }
105	        }
106	        false
107	    };
108	
109	    EnabledAxiDirections {
110	        read: group_enabled(&[(READ_ADDR, "_write"), (READ_DATA, "_read")]),
111	        write: group_enabled(&[
112	            (WRITE_ADDR, "_write"),
113	            (WRITE_DATA, "_write"),
114	            (WRITE_RESP, "_read"),
115	        ]),
116	    }
117	}
