132	fn strip_verilog_comments(source: &str) -> String {
133	    let mut result = String::with_capacity(source.len());
134	    let mut chars = source.chars().peekable();
135	    while let Some(ch) = chars.next() {
136	        if ch != '/' {
137	            result.push(ch);
138	            continue;
139	        }
140	        match chars.peek().copied() {
141	            Some('/') => {
142	                let _ = chars.next();
143	                for comment in chars.by_ref() {
144	                    if comment == '\n' {
145	                        result.push('\n');
146	                        break;
147	                    }
148	                }
149	            }
150	            Some('*') => {
151	                let _ = chars.next();
152	                let mut previous = '\0';
153	                for comment in chars.by_ref() {
154	                    if previous == '*' && comment == '/' {
155	                        break;
156	                    }
157	                    previous = comment;
158	                }
159	                result.push(' ');
160	            }
161	            _ => result.push(ch),
162	        }
163	    }
164	    result
165	}
