167	fn has_unconditional_zero_assign(source: &str, port: &str) -> bool {
168	    source.split(';').any(|statement| {
169	        let statement = statement.trim();
170	        let Some(assign) = statement.strip_prefix("assign") else {
171	            return false;
172	        };
173	        let Some((lhs, rhs)) = assign.split_once('=') else {
174	            return false;
175	        };
176	        lhs.trim() == port && is_zero_literal(rhs.trim())
177	    })
178	}
179	
180	fn is_zero_literal(literal: &str) -> bool {
181	    let mut literal = literal.trim();
182	    while let Some(inner) = literal
183	        .strip_prefix('(')
184	        .and_then(|value| value.strip_suffix(')'))
185	    {
186	        literal = inner.trim();
187	    }
188	    let compact = literal.replace('_', "");
189	    if compact == "0" || compact == "'0" {
190	        return true;
191	    }
192	    let Some((width, value)) = compact.split_once('\'') else {
193	        return false;
194	    };
195	    if width.is_empty() || !width.chars().all(|ch| ch.is_ascii_digit()) {
196	        return false;
197	    }
198	    let value = value
199	        .strip_prefix('s')
200	        .or_else(|| value.strip_prefix('S'))
201	        .unwrap_or(value);
202	    let Some(digits) = value
203	        .get(1..)
204	        .filter(|_| value.starts_with(['b', 'B', 'o', 'O', 'd', 'D', 'h', 'H']))
205	    else {
206	        return false;
207	    };
208	    !digits.is_empty() && digits.chars().all(|ch| ch == '0')
209	}
