221	    child_rtl: &VerilogModule,
222	    child_port: &str,
223	    bridge_base: &str,
224	    offset_signal: &str,
225	) -> Vec<PortArg> {
226	    let mut ports = Vec::new();
227	    for &tag in TAGS {
228	        let prefix = format!("{child_port}_{tag}");
229	        for &suffix in tag_suffixes(tag) {
230	            if let Some(port) = child_rtl.find_port_by_affixes(&prefix, suffix) {
231	                ports.push(PortArg::new(
