242	                            child_connection_expr(bridge_base, tag, suffix),
243	                        ));
244	                    }
245	                }
246	            }
247	        }
248	        if tag.ends_with("_addr") {
249	            if let Some(port) = child_rtl.find_port_by_affixes(&prefix, "_offset") {
250	                ports.push(PortArg::new(port.name.clone(), Expr::ident(offset_signal)));
251	            }
252	        }
253	    }
