289	            ArgCategory::Istream | ArgCategory::Istreams => {
290	                // Input stream: connect with ISTREAM_SUFFIXES
291	                for suffix in ISTREAM_SUFFIXES {
292	                    let signal = Expr::ident(stream_signal(&arg.arg, suffix));
293	                    port_args.push(PortArg::new(
294	                        resolve_child_stream_port(child_port, suffix),
295	                        signal.clone(),
296	                    ));
297	                    if matches!(*suffix, "_dout" | "_empty_n") {
298	                        if let Some(peek_port) = resolve_child_stream_peek_port(child_port, suffix)
299	                        {
300	                            port_args.push(PortArg::new(
301	                                peek_port,
302	                                Expr::ident(peek_signal(&arg.arg, suffix)),
303	                            ));
304	                        }
305	                    }
306	                }
307	            }
308	            ArgCategory::Ostream | ArgCategory::Ostreams => {
309	                // Output stream: connect with OSTREAM_SUFFIXES
310	                for suffix in OSTREAM_SUFFIXES {
311	                    port_args.push(PortArg::new(
312	                        resolve_child_stream_port(child_port, suffix),
313	                        Expr::ident(stream_signal(&arg.arg, suffix)),
314	                    ));
315	                }
316	            }
317	            ArgCategory::Mmap | ArgCategory::AsyncMmap => {
318	                // Connect to per-instance pipeline offset
319	                let offset_sig = format!("{instance_name}__{child_port}_offset");
320	                // Bind M-AXI channel ports:
321	                // If crossbar exists (slave index present), bind to downstream wires
322	                // Otherwise bind directly to upstream parent m_axi signals
323	                let m_axi_wire_prefix = mmap_bindings.wire_prefix(&arg.arg);
324	                let m_axi_wire_id_width = mmap_bindings.wire_id_width(&arg.arg);
325	                let child_m_axi_id_width = mmap_bindings.child_id_width(&arg.arg);
326	                if matches!(arg.cat, ArgCategory::AsyncMmap) {
327	                    if child_has_direct_mmap_ports(child_rtl, child_port) {
328	                        let child_rtl_filter =
329	                            if child_has_direct_mmap_offset(child_rtl, child_port) {
330	                                None
331	                            } else {
332	                                child_rtl
333	                            };
334	                        add_direct_mmap_portargs(
335	                            &mut port_args,
336	                            child_port,
337	                            &offset_sig,
338	                            &m_axi_wire_prefix,
339	                            m_axi_wire_id_width,
340	                            child_m_axi_id_width,
341	                            child_rtl_filter,
342	                            child_rtl,
343	                        );
344	                    } else if let Some(module) = child_rtl {
345	                        let bridge_base =
346	                            crate::async_mmap::bridge_base_from_m_axi_prefix(&m_axi_wire_prefix);
347	                        port_args.extend(crate::async_mmap::child_portargs(
348	                            module,
349	                            child_port,
350	                            &bridge_base,
351	                            &offset_sig,
352	                        ));
353	                    }
354	                } else {
355	                    add_direct_mmap_portargs(
356	                        &mut port_args,
357	                        child_port,
358	                        &offset_sig,
359	                        &m_axi_wire_prefix,
360	                        m_axi_wire_id_width,
361	                        child_m_axi_id_width,
362	                        None,
363	                        child_rtl,
364	                    );
365	                }
366	            }
367	            ArgCategory::Immap | ArgCategory::Ommap => {
368	                // Other categories: direct connection
369	                port_args.push(PortArg::new(
370	                    sanitize_array_name(child_port),
371	                    Expr::ident(sanitize_array_name(&arg.arg)),
372	                ));
373	            }
374	        }
375	    }
376	
377	    ModuleInstance::new(child_task_name, instance_name).with_ports(port_args)
378	}
