388	#[allow(
389	    clippy::too_many_arguments,
390	    reason = "mmap port arg wiring needs all 8 parameters"
391	)]
392	fn add_direct_mmap_portargs(
393	    port_args: &mut Vec<PortArg>,
394	    child_port: &str,
395	    offset_sig: &str,
396	    m_axi_wire_prefix: &str,
397	    m_axi_wire_id_width: Option<u32>,
398	    child_m_axi_id_width: Option<u32>,
399	    child_rtl_filter: Option<&VerilogModule>,
400	    child_rtl_for_width: Option<&VerilogModule>,
401	) {
402	    let offset_port = format!("{child_port}_offset");
403	    if child_rtl_filter.is_none_or(|module| module.find_port(&offset_port).is_some()) {
404	        port_args.push(PortArg::new(offset_port, Expr::ident(offset_sig)));
405	    }
406	    for suffix in tapa_protocol::M_AXI_SUFFIXES_COMPACT {
407	        let child_axi_port = format!("m_axi_{child_port}{suffix}");
408	        if child_rtl_filter.is_none_or(|module| module.find_port(&child_axi_port).is_some()) {
409	            let wire_name = format!("{m_axi_wire_prefix}{suffix}");
410	            port_args.push(PortArg::new(
411	                child_axi_port.as_str(),
412	                direct_mmap_connection_expr(
413	                    child_rtl_for_width,
414	                    &child_axi_port,
415	                    &wire_name,
416	                    suffix,
417	                    m_axi_wire_id_width,
418	                    child_m_axi_id_width,
419	                ),
420	            ));
421	        }
422	    }
423	}
424	
425	fn direct_mmap_connection_expr(
426	    child_rtl: Option<&VerilogModule>,
427	    child_axi_port: &str,
428	    wire_name: &str,
429	    suffix: &str,
430	    m_axi_wire_id_width: Option<u32>,
431	    child_m_axi_id_width: Option<u32>,
432	) -> Expr {
433	    let is_id = matches!(suffix, "_ARID" | "_AWID" | "_BID" | "_RID");
434	    let Some(target_width) = m_axi_wire_id_width else {
435	        return Expr::ident(wire_name);
436	    };
437	    if !is_id || target_width <= 1 {
438	        return Expr::ident(wire_name);
439	    }
440	    let child_width = child_m_axi_id_width
441	        .or_else(|| {
442	            child_rtl
443	                .and_then(|module| module.find_port(child_axi_port))
444	                .and_then(tapa_rtl::port::Port::bit_width)
445	        })
446	        .unwrap_or(target_width);
447	    if child_width >= target_width {
448	        return Expr::ident(wire_name);
449	    }
450	    Expr::range(
451	        Expr::ident(wire_name),
452	        Expr::int(u64::from(child_width - 1)),
453	        Expr::int(0),
454	    )
455	}
