469	fn array_name_parts(name: &str) -> Option<(&str, &str, &str)> {
470	    let left = name.find('[')?;
471	    let right = name[left + 1..].find(']')? + left + 1;
472	    Some((&name[..left], &name[left + 1..right], &name[right + 1..]))
473	}
