475	/// Resolve the peek port belonging to stream `name` on `module`. Array
476	/// elements (`in_q[0]`) map to `{base}_peek_{idx}{tail}{suffix}`; scalar
477	/// streams go through the usual `{name}{infix}_peek{suffix}` infix search.
478	fn resolve_peek_port_name(module: &VerilogModule, name: &str, suffix: &str) -> Option<String> {
479	    if let Some((base, idx, tail)) = array_name_parts(name) {
480	        let candidate = format!("{base}_peek_{idx}{tail}{suffix}");
481	        return module.find_port(&candidate).map(|p| p.name.clone());
482	    }
483	    module
484	        .get_port_of(name, &format!("_peek{suffix}"))
485	        .map(|p| p.name.clone())
486	}
