344	    #[allow(
345	        clippy::too_many_lines,
346	        reason = "child control wiring is kept together so bundle slices remain auditable"
347	    )]
348	    pub(super) fn instantiate_child(
349	        &self,
350	        state: &mut TopologyWithRtl,
351	        task_name: &str,
352	        logical_instance: &str,
353	        signals: &InstanceSignals,
354	    ) -> Result<(), CodegenError> {
355	        let child = self.children.get(logical_instance).ok_or_else(|| {
356	            invalid_floorplan(format!(
357	                "generated child '{logical_instance}' has no control plan",
358	            ))
359	        })?;
360	        let Some(module) = state.module_map.get_mut(task_name) else {
361	            return Ok(());
362	        };
363	        let prefix = control_wire_prefix(logical_instance);
364	        let launch_input = format!("{prefix}__launch_input");
365	        let launch_output = format!("{prefix}__launch_output");
366	        let reset_n = Self::child_reset_name(logical_instance);
367	        let local_completion = format!("{prefix}__local_completion");
368	
369	        add_width_wire(module, &launch_input, child.launch_width)?;
370	        add_width_wire(module, &launch_output, child.launch_width)?;
371	        module.add_signal(wire(&reset_n))?;
372	        module.add_signal(wire(&local_completion))?;
373	
374	        let mut launch_fields = child
375	            .payload
376	            .iter()
377	            .rev()
378	            .map(|field| field.source.clone())
379	            .collect::<Vec<_>>();
380	        if !child.is_autorun {
381	            launch_fields.push(Expr::ident(GLOBAL_RELEASE));
382	        }
383	        launch_fields.push(Expr::ident(GLOBAL_START));
384	        module.add_assign(ContinuousAssign::new(
385	            Expr::ident(&launch_input),
386	            concat_or_scalar(launch_fields),
387	        ));
388	
389	        instantiate_or_connect_pipeline(
390	            module,
391	            logical_instance,
392	            ControlChannel::Launch,
393	            child.launch.as_ref(),
394	            child.launch_width,
395	            Expr::ident(&launch_input),
396	            Expr::ident(&launch_output),
397	        );
398	        instantiate_or_connect_pipeline(
399	            module,
400	            logical_instance,
401	            ControlChannel::Reset,
402	            child.reset.as_ref(),
403	            1,
404	            Expr::ident(HANDSHAKE_RST_N),
405	            Expr::ident(&reset_n),
406	        );
407	
408	        for field in &child.payload {
409	            add_width_wire(module, &field.output, field.width)?;
410	            module.add_assign(ContinuousAssign::new(
411	                Expr::ident(&field.output),
412	                select_bits(&launch_output, field.lsb, field.width),
413	            ));
414	        }
415	
416	        let launch_start = if child.launch_width == 1 {
417	            Expr::ident(&launch_output)
418	        } else {
419	            Expr::index(Expr::ident(&launch_output), Expr::int(0))
420	        };
421	        let launch_release = if child.is_autorun {
422	            Expr::lit("1'b0")
423	        } else {
424	            Expr::index(Expr::ident(&launch_output), Expr::int(1))
425	        };
426	        let child_done = if child.is_autorun {
427	            Expr::lit("1'b0")
428	        } else {
429	            Expr::ident(signals.done_name())
430	        };
431	        let child_ready = if child.is_autorun {
432	            Expr::lit("1'b0")
433	        } else {
434	            Expr::ident(signals.ready_name())
435	        };
436	        let child_idle = if child.is_autorun {
437	            Expr::lit("1'b0")
438	        } else {
439	            Expr::ident(signals.idle_name())
440	        };
441	        module.add_instance(
442	            ModuleInstance::new(
443	                "tapa_local_controller",
444	                local_controller_instance_name(logical_instance),
445	            )
446	            .with_params(vec![ParamArg::new(
447	                "AUTORUN",
448	                Expr::int(u64::from(child.is_autorun)),
449	            )])
450	            .with_ports(vec![
451	                PortArg::new("ap_clk", Expr::ident(HANDSHAKE_CLK)),
452	                PortArg::new("reset_n", Expr::ident(&reset_n)),
453	                PortArg::new("launch_start", launch_start),
454	                PortArg::new("launch_release", launch_release),
455	                PortArg::new("child_done", child_done),
456	                PortArg::new("child_ready", child_ready),
457	                PortArg::new("child_idle", child_idle),
458	                PortArg::new("child_start", Expr::ident(signals.start_name())),
459	                PortArg::new("completion", Expr::ident(&local_completion)),
460	            ]),
461	        );
462	
463	        if !child.is_autorun {
464	            instantiate_or_connect_pipeline(
465	                module,
466	                logical_instance,
467	                ControlChannel::Completion,
468	                child.completion.as_ref(),
469	                1,
470	                Expr::ident(&local_completion),
471	                Expr::ident(signals.is_done_name()),
472	            );
473	        }
474	        Ok(())
475	    }
