477	    pub(super) fn instantiate_global(
478	        &self,
479	        state: &mut TopologyWithRtl,
480	        task_name: &str,
481	        completion_signals: &[String],
482	    ) -> Result<(), CodegenError> {
483	        let Some(module) = state.module_map.get_mut(task_name) else {
484	            return Ok(());
485	        };
486	        module.add_signal(wire(GLOBAL_START))?;
487	        module.add_signal(wire(GLOBAL_RELEASE))?;
488	        module.add_signal(wire(CHILDREN_DONE))?;
489	        module.add_signal(wire(CHILDREN_CLEAR))?;
490	        module.add_signal(wire(FABRIC_RESET_N))?;
491	
492	        let done = logical_reduction(
493	            completion_signals
494	                .iter()
495	                .map(|signal| Expr::ident(signal.clone())),
496	            "1'b1",
497	        );
498	        let clear = logical_reduction(
499	            completion_signals
500	                .iter()
501	                .map(|signal| Expr::logical_not(Expr::ident(signal.clone()))),
502	            "1'b1",
503	        );
504	        module.add_assign(ContinuousAssign::new(Expr::ident(CHILDREN_DONE), done));
505	        module.add_assign(ContinuousAssign::new(Expr::ident(CHILDREN_CLEAR), clear));
506	        module.add_instance(
507	            ModuleInstance::new("tapa_global_controller", global_controller_instance_name())
508	                .with_params(vec![ParamArg::new(
509	                    "FLUSH_CYCLES",
510	                    Expr::int(u64::from(self.flush_cycles)),
511	                )])
512	                .with_ports(vec![
513	                    PortArg::new("ap_clk", Expr::ident(HANDSHAKE_CLK)),
514	                    PortArg::new("ap_rst_n", Expr::ident(HANDSHAKE_RST_N)),
515	                    PortArg::new("ap_start", Expr::ident(HANDSHAKE_START)),
516	                    PortArg::new("children_done", Expr::ident(CHILDREN_DONE)),
517	                    PortArg::new("children_clear", Expr::ident(CHILDREN_CLEAR)),
518	                    PortArg::new("launch_start", Expr::ident(GLOBAL_START)),
519	                    PortArg::new("launch_release", Expr::ident(GLOBAL_RELEASE)),
520	                    PortArg::new("fabric_reset_n", Expr::ident(FABRIC_RESET_N)),
521	                    PortArg::new("ap_done", Expr::ident(HANDSHAKE_DONE)),
522	                    PortArg::new("ap_ready", Expr::ident(HANDSHAKE_READY)),
523	                    PortArg::new("ap_idle", Expr::ident(HANDSHAKE_IDLE)),
524	                ]),
525	        );
526	        Ok(())
527	    }
528	}
