834	fn add_resource_constraints(
835	    lp: &mut LpModel,
836	    graph: &FloorGraph,
837	    device: &Device,
838	    domains: &[Vec<Coor>],
839	    usage_limit: f64,
840	    constraints: &PlacementConstraints,
841	    x: &[Vec<LpVar>],
842	) -> Result<(), IlpError> {
843	    let active_regions: BTreeSet<Coor> = domains.iter().flatten().copied().collect();
844	    for region in active_regions {
845	        let total = device
846	            .island_area(&region)
847	            .ok_or_else(|| IlpError::InvalidRegion(region.region_name()))?;
848	        for resource in Resource::ALL {
849	            let terms: Vec<(f64, LpVar)> = graph
850	                .vertices()
851	                .iter()
852	                .enumerate()
853	                .filter_map(|(vi, vertex)| {
854	                    let ci = domains[vi]
855	                        .iter()
856	                        .position(|candidate| *candidate == region)?;
857	                    Some((u64_as_f64(resource.amount(&vertex.area)), x[vi][ci]))
858	                })
859	                .collect();
860	
861	            let max_rhs = lookup_limit(&constraints.max_resource_limits, &region, resource)
862	                .map_or_else(
863	                    || u64_as_f64(scaled_amount(resource.amount(&total), usage_limit)),
864	                    |limit| u64_as_f64(resource.amount(&total)) * limit,
865	                );
866	            lp.add_constraint(
867	                format!("node_{}_{}_usage", region.region_name(), resource.name()),
868	                LinExpr::sum(terms.iter().copied()),
869	                Comparison::Le,
870	                max_rhs,
871	            );
872	
873	            if let Some(limit) = lookup_limit(&constraints.min_resource_limits, &region, resource) {
874	                let min_rhs = u64_as_f64(resource.amount(&total)) * limit;
875	                if min_rhs > 0.0 && terms.iter().all(|(coef, _)| *coef == 0.0) {
876	                    return Err(IlpError::ImpossibleMinimum {
877	                        region: region.region_name(),
878	                        resource: resource.name(),
879	                    });
880	                }
881	                lp.add_constraint(
882	                    format!("node_{}_{}_usage_ge", region.region_name(), resource.name()),
883	                    LinExpr::sum(terms),
884	                    Comparison::Ge,
885	                    min_rhs,
886	                );
887	            }
888	        }
889	    }
890	    Ok(())
891	}
