908	/// Per-cut wire constraint over only the sparse route variables that exist.
909	fn add_cut_constraints(
910	    lp: &mut LpModel,
911	    graph: &FloorGraph,
912	    domains: &[Vec<Coor>],
913	    cuts: &[Cut],
914	    y: &[Vec<Vec<LpVar>>],
915	) {
916	    for cut in cuts {
917	        let lhs: BTreeSet<Coor> = cut.lhs.iter().copied().collect();
918	        let rhs: BTreeSet<Coor> = cut.rhs.iter().copied().collect();
919	        let mut terms = Vec::new();
920	        for (ei, edge) in graph.placement_edges().iter().enumerate() {
921	            for (src_ci, src_region) in domains[edge.src].iter().enumerate() {
922	                for (dst_ci, dst_region) in domains[edge.dst].iter().enumerate() {
923	                    let crosses = (lhs.contains(src_region) && rhs.contains(dst_region))
924	                        || (rhs.contains(src_region) && lhs.contains(dst_region));
925	                    if crosses {
926	                        terms.push((f64::from(edge.width), y[ei][src_ci][dst_ci]));
927	                    }
928	                }
929	            }
930	        }
931	        lp.add_constraint(
932	            format!("cut_{}_capacity", cut.name),
933	            LinExpr::sum(terms),
934	            Comparison::Le,
935	            u64_as_f64(cut.capacity),
936	        );
937	    }
938	}
