968	/// Twice the exact midpoint, so half-integer rectangular centroids remain
969	/// exact until the final LP coefficient conversion.
970	fn centroid_twice(device: &Device, region: &Coor) -> Result<(i64, i64), IlpError> {
971	    let dl = device
972	        .slot(region.dl_x, region.dl_y)
973	        .ok_or_else(|| IlpError::InvalidRegion(region.region_name()))?;
974	    let ur = device
975	        .slot(region.ur_x, region.ur_y)
976	        .ok_or_else(|| IlpError::InvalidRegion(region.region_name()))?;
977	    Ok((dl.centroid_x + ur.centroid_x, dl.centroid_y + ur.centroid_y))
978	}
