940	/// Width-weighted adjusted centroid distance plus the formulation's constant
941	/// one.
942	fn add_objective(
943	    lp: &mut LpModel,
944	    graph: &FloorGraph,
945	    device: &Device,
946	    domains: &[Vec<Coor>],
947	    y: &[Vec<Vec<LpVar>>],
948	) -> Result<(), IlpError> {
949	    let mut objective = Vec::new();
950	    for (ei, edge) in graph.placement_edges().iter().enumerate() {
951	        for (src_ci, src) in domains[edge.src].iter().enumerate() {
952	            let src_centroid = centroid_twice(device, src)?;
953	            for (dst_ci, dst) in domains[edge.dst].iter().enumerate() {
954	                let dst_centroid = centroid_twice(device, dst)?;
955	                let distance_twice = (src_centroid.0 - dst_centroid.0).abs()
956	                    + VERTICAL_DIST_PENALTY * (src_centroid.1 - dst_centroid.1).abs();
957	                if distance_twice != 0 {
958	                    let coefficient = f64::from(edge.width) * i64_as_f64(distance_twice) / 2.0;
959	                    objective.push((coefficient, y[ei][src_ci][dst_ci]));
960	                }
961	            }
962	        }
963	    }
964	    lp.set_objective(LinExpr::sum(objective).plus_constant(1.0));
965	    Ok(())
966	}
