120	/// sides specify a limit, the north/east slot's south/west value wins.
121	fn finite_boundaries(device: &Device) -> Vec<Boundary> {
122	    let mut out = Vec::new();
123	    for y in 0..device.rows {
124	        for x in 0..device.cols {
125	            let Some(slot) = device.slot(x, y) else {
126	                continue;
127	            };
128	            if x + 1 < device.cols {
129	                let Some(right) = device.slot(x + 1, y) else {
130	                    continue;
131	                };
132	                let capacity = finite_capacity(right.wire_cap.west)
133	                    .or_else(|| finite_capacity(slot.wire_cap.east));
134	                if let Some(capacity) = capacity {
135	                    out.push(Boundary {
136	                        a: (x, y),
137	                        b: (x + 1, y),
138	                        capacity,
139	                    });
140	                }
141	            }
142	            if y + 1 < device.rows {
143	                let Some(up) = device.slot(x, y + 1) else {
144	                    continue;
145	                };
146	                let capacity = finite_capacity(up.wire_cap.south)
147	                    .or_else(|| finite_capacity(slot.wire_cap.north));
148	                if let Some(capacity) = capacity {
149	                    out.push(Boundary {
150	                        a: (x, y),
151	                        b: (x, y + 1),
152	                        capacity,
153	                    });
154	                }
155	            }
156	        }
157	    }
158	    out
159	}
