162	fn fallback_boundaries(device: &Device) -> Vec<Boundary> {
163	    let mut out = Vec::new();
164	    for y in 0..device.rows {
165	        for x in 0..device.cols {
166	            if x + 1 < device.cols && device.slot(x, y).is_some() && device.slot(x + 1, y).is_some()
167	            {
168	                out.push(Boundary {
169	                    a: (x, y),
