197	/// Whether `path` uses the hop across `boundary` (in either direction).
198	fn path_crosses(path: &[Cell], boundary: &Boundary) -> bool {
199	    path.windows(2).any(|hop| {
200	        (hop[0] == boundary.a && hop[1] == boundary.b)
201	            || (hop[0] == boundary.b && hop[1] == boundary.a)
202	    })
