205	/// Check endpoint, grid, simplicity, and adjacency invariants for a route.
206	fn validate_path(
207	    net_index: usize,
208	    net: &RouteNet,
209	    path: &[Cell],
210	    device: &Device,
211	) -> Result<(), RouteError> {
212	    if path.first().copied() != Some(net.src) {
213	        return Err(RouteError::InvalidPath {
214	            net_index,
215	            reason: format!("path must start at {:?}", net.src),
216	        });
217	    }
218	    if path.last().copied() != Some(net.dst) {
219	        return Err(RouteError::InvalidPath {
220	            net_index,
221	            reason: format!("path must end at {:?}", net.dst),
222	        });
223	    }
224	    if let Some(&cell) = path.iter().find(|&&(x, y)| device.slot(x, y).is_none()) {
225	        return Err(RouteError::InvalidPath {
226	            net_index,
227	            reason: format!("slot {cell:?} is outside the device"),
228	        });
229	    }
230	    if path.iter().copied().collect::<BTreeSet<_>>().len() != path.len() {
231	        return Err(RouteError::InvalidPath {
232	            net_index,
233	            reason: "path revisits a slot".to_string(),
234	        });
235	    }
236	    if let Some([from, to]) = path
237	        .windows(2)
238	        .find(|hop| hop[0].0.abs_diff(hop[1].0) + hop[0].1.abs_diff(hop[1].1) != 1)
239	    {
240	        return Err(RouteError::InvalidPath {
241	            net_index,
242	            reason: format!("non-adjacent hop {from:?} -> {to:?}"),
243	        });
244	    }
245	    Ok(())
246	}
