353	fn prepare_plan(
354	    state: &WorkState,
355	    inputs: &PlanInputs,
356	) -> Result<(crate::device::model::Device, FloorGraph), PlanError> {
357	    let part_num = state.flow.part_num.as_deref().ok_or(PlanError::NoPartNum)?;
358	    let device = select_device(part_num)?;
359	    validate_memory_platform(state, &device, !inputs.memory.is_empty())?;
360	    let mut validated_banks = std::collections::BTreeSet::new();
361	    for bank in inputs.memory.iter().map(|interface| interface.bank) {
362	        if !validated_banks.insert(bank) {
363	            continue;
364	        }
365	        let matches = device.slots_with_tag(&bank.to_string()).count();
366	        if matches != 1 {
367	            return Err(PlanError::BankTag { bank, matches });
368	        }
369	    }
370	    let flat = tapa_ir::flatten(&state.graph)?;
371	    let active_control = inputs.control.filter(|_| {
372	        flat.tasks
373	            .get(&flat.top)
374	            .is_some_and(|top| !top.tasks.is_empty())
375	    });
376	    let control_anchor = active_control
377	        .map(|control| select_control_anchor(&device, control))
378	        .transpose()?
379	        .flatten();
380	    let graph =
381	        FloorGraph::build_with_interfaces(&flat, &inputs.memory, active_control, control_anchor)?;
382	    Ok((device, graph))
383	}
