343	/// Resolve FIFO width from the producer child's attached RTL module.
344	///
345	/// Looks for the producer's bound stream port on the parsed child RTL and uses
346	/// its width, falling back to the producer task's topology port width. Errors
347	/// when neither yields a width, which for a well-formed program only happens
348	/// if the producer task, its instance, or its bound stream port is missing.
349	fn resolve_fifo_width(
350	    state: &TopologyWithRtl,
351	    producer: &FifoProducer,
352	    fifo_name: &str,
353	) -> Result<u32, CodegenError> {
354	    // Check attached RTL module for producer port width
355	    if let Some(mm) = state.module_map.get(producer.task_name.as_str()) {
356	        if let Some(port_name) = producer.port_name.as_deref() {
357	            for suffix in ["_din", "_dout"] {
358	                if let Some(port) = mm.inner.get_port_of(port_name, suffix) {
359	                    if let Some(width) = port.bit_width() {
360	                        return Ok(width);
361	                    }
362	                }
363	            }
364	        } else {
365	            // Incomplete external topology may not identify the logical port;
366	            // use the first matching stream signal as a best-effort width.
367	            for port in &mm.inner.ports {
368	                if port.name.ends_with("_dout") || port.name.ends_with("_din") {
369	                    if let Some(width) = port.bit_width() {
370	                        return Ok(width);
371	                    }
372	                }
373	            }
374	        }
375	    }
376	    // Fallback: check topology port definitions for the producer task
377	    if let Some(task) = state.design.tasks.get(producer.task_name.as_str()) {
378	        if let Some(port_name) = producer.port_name.as_deref() {
379	            let logical_port_name =
380	                tapa_rtl::module::match_array_name(port_name).map_or(port_name, |(base, _)| base);
381	            if let Some(port) = task
382	                .ports
383	                .iter()
384	                .find(|port| port.name == logical_port_name && port.cat.is_output_stream())
385	            {
386	                return Ok(port.width.saturating_add(1));
387	            }
388	        }
389	        for port in &task.ports {
390	            if port.cat.is_output_stream() {
391	                return Ok(port.width.saturating_add(1));
392	            }
393	        }
394	    }
395	    Err(CodegenError::FifoWidthUnresolved(fifo_name.to_owned()))
396	}
